import{_ as a,o as d,c as e,ag as r}from"./chunks/framework.C5oN-8Wt.js";const s="/cns_master_docs/teaching-v0.2.0-alpha/09-symbols.svg",g=JSON.parse('{"title":"09 从数据编号到星座点，再作出判决","description":"","frontmatter":{},"headers":[],"relativePath":"v0.2.0-alpha/learn/09-symbols/index.md","filePath":"v0.2.0-alpha/learn/09-symbols/index.md"}'),o={name:"v0.2.0-alpha/learn/09-symbols/index.md"};function n(l,t,i,h,p,c){return d(),e("div",null,[...t[0]||(t[0]=[r(`<h1 id="_09-从数据编号到星座点-再作出判决" tabindex="-1">09 从数据编号到星座点，再作出判决 <a class="header-anchor" href="#_09-从数据编号到星座点-再作出判决" aria-label="Permalink to &quot;09 从数据编号到星座点，再作出判决&quot;">​</a></h1><p>无人机的电池状态、速度或位置可以先表示成数字，再按通信协议组织、编码并发送。本课只取其中一小步：<strong>假设数据已变成 0、1、2、3 四种编号，怎样把编号变成信号坐标，再从坐标判回编号？</strong></p><p>适用 CNS Master <strong>v0.2.0-alpha</strong>。先完成<a href="./../07-iq/">07 I/Q</a>。本例输入是软件生成的随机编号，没有真实电池值、坐标数据或通信报文。</p><p><a href="../../../downloads/teaching-v0.2.0-alpha/09-symbols.cnsproj" download>下载本课工程：09-symbols.cnsproj</a></p><h2 id="先认识比特、码元与星座" tabindex="-1">先认识比特、码元与星座 <a class="header-anchor" href="#先认识比特、码元与星座" aria-label="Permalink to &quot;先认识比特、码元与星座&quot;">​</a></h2><p><strong>比特（bit）<strong>只有 0、1 两种值。两个比特可以组合成 <code>00、01、10、11</code> 四种情况。发送端若把四种情况分别指定给四个信号状态，每选一次状态，就发送一个</strong>码元</strong>。</p><p>本课用 0—3 作为码元的编号，即<strong>码元索引</strong>。编号不是信号幅度：索引 3 不表示“幅度为 3”。<strong>星座点</strong>是与编号相对应的 I/Q 坐标。<strong>映射</strong>按编号查点；<strong>硬判决</strong>则从收到的坐标选择最近的已知点，只输出编号。</p><p>本例采用 <strong>QPSK</strong> 四点星座。若明确按 <code>00→0、01→1、10→2、11→3</code> 组织，每码元可以表达 2 bit；工程本身只处理编号，不自动打包比特。与之相比，BPSK 只有两个状态，每码元可表达 1 bit。状态数增加并不自动保证实际链路更快或更可靠。</p><h2 id="接线与参数理由" tabindex="-1">接线与参数理由 <a class="header-anchor" href="#接线与参数理由" aria-label="Permalink to &quot;接线与参数理由&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>随机码元发生器 1.out → 符号映射器 1.in</span></span>
<span class="line"><span>                              out → 复数增益器 1.in</span></span>
<span class="line"><span>                                               out → 符号判决器 1.in</span></span></code></pre></div><table tabindex="0"><thead><tr><th>位置</th><th>本课值</th><th>为什么选它</th></tr></thead><tbody><tr><td>随机码元发生器 1</td><td>QPSK；最小索引 0（包含）；最大索引 4（不包含）；固定种子 7</td><td>产生 0、1、2、3 四种编号，重新准备可从同一随机起点比较</td></tr><tr><td>码元率</td><td>1024 符号/s</td><td>每秒产生 1024 个编号；本课每码元映射为一个复数样本</td></tr><tr><td>源、映射器、判决器</td><td>均为相同 QPSK 预设；D＝1</td><td>使用同一套编号与坐标定义，避免表的含义不一致</td></tr><tr><td>复数增益器 1</td><td>增益实部 1，虚部 0，向量长度 1</td><td>基线不改变坐标；稍后只缩小坐标距离</td></tr></tbody></table><p>QPSK 预设点表按编号排列如下。<code>0.7071</code> 是 <code>1/√2</code> 的近似值，每点到原点的距离约为 1。</p><table tabindex="0"><thead><tr><th>编号</th><th>I</th><th>Q</th><th>方位</th></tr></thead><tbody><tr><td>0</td><td>−0.7071</td><td>−0.7071</td><td>左下</td></tr><tr><td>1</td><td>−0.7071</td><td>+0.7071</td><td>左上</td></tr><tr><td>2</td><td>+0.7071</td><td>−0.7071</td><td>右下</td></tr><tr><td>3</td><td>+0.7071</td><td>+0.7071</td><td>右上</td></tr></tbody></table><p>表的<strong>顺序</strong>也有意义。四个点摆在相同位置、却给它们不同编号，接收端仍可能判回错误的数据。</p><h2 id="逐步操作" tabindex="-1">逐步操作 <a class="header-anchor" href="#逐步操作" aria-label="Permalink to &quot;逐步操作&quot;">​</a></h2><ol><li>下载工程。Shift+F5 停止其他本地任务，用 Ctrl+O 打开。检查源、映射器和判决器均使用 QPSK；不要只检查其中一个。</li><li>先画出上表四个点，并预测输入索引 2 应落在哪一象限。再按 F5 运行。</li><li>输入／判决的观察器参数页应捕获“随机码元发生器 1 → 码元输出”和“符号判决器 1 → 码元输出”。输出页用“曲线叠加”，缩短横轴范围查看约 <strong>0.016 s</strong> 的数据，逐个读 0—3 的索引。</li><li>另两个观察器分别只捕获“符号映射器 1 → 星座输出”以及“复数增益器 1 → 输出”，在输出页选“星座”。每个星座观察器只留一路复数捕获，分别采用相同轴范围和等比例显示。</li><li>若自行重建，用“编辑 → 插入 → 观察器”，参数页输入节点名并点选候选。“添加捕获变量”用于把输入和判决两路放到一起；码元输出不选择频谱，星座观察器也不添加第二路。</li><li>运行后 Shift+F5 停止，查看保留数据。相同时间位置上的输入与判决编号应相同；完全重合时图上可能只看出上层那条颜色，结合图例确认两路确实绑定不同节点。</li><li>对照星座的点位与编号表，说明“0—3 的时间序列”和“四个 I/Q 点”是同一批信息在不同处理步骤的表示。</li></ol><h2 id="预期图像与解释" tabindex="-1">预期图像与解释 <a class="header-anchor" href="#预期图像与解释" aria-label="Permalink to &quot;预期图像与解释&quot;">​</a></h2><p><a href="/cns_master_docs/teaching-v0.2.0-alpha/09-symbols.svg"><img src="`+s+'" alt="实际 GNU 输出：输入与判决索引相同，正实增益减半后 QPSK 星座半径减半"></a></p><p>右图为解释缩放，将两次真实运行的坐标绘在同一参考轴上；下载工程的两个星座观察器各绑定一路复数来源，实际操作时分别读同一轴范围。左图索引来自实际序列，逐项一致性由整段数据核对，不能只凭几处可见点认定。</p><p>随机输入图按时间在 0、1、2、3 之间跳变。映射后的星座图应聚集为四个离散位置，不是上一课复数单音的圆周点集。判决输出在本课理想条件下恢复原编号。</p><p>图上点之间若有连线，那是显示方式，不表示本例实现了平滑的点间过渡。本课每个码元只取一个离散坐标，尚未加入把离散样本变成适合实际传输波形的脉冲成形，也没有无线电载波、接收同步或报文解析。</p><p>码元率为 1024 符号/s；在约定每符号 2 bit 的理想编号关系下，对应 <strong>2048 bit/s 的未计开销映射速率</strong>。这不能直接称为无人机可用数据吞吐量：真实报文、编码、同步和重传等还会占用资源。</p><h2 id="单参数对照-只把增益实部改成-0-5" tabindex="-1">单参数对照：只把增益实部改成 0.5 <a class="header-anchor" href="#单参数对照-只把增益实部改成-0-5" aria-label="Permalink to &quot;单参数对照：只把增益实部改成 0.5&quot;">​</a></h2><ol><li>停止，将复数增益器 1 的“增益实部”从 <strong>1 改为 0.5</strong>；虚部仍为 0，其他参数不变，按 F5。</li><li>在同样的轴范围下比较增益前后星座：后者 I、Q 绝对值约为 <strong>0.3536</strong>，点到原点的距离约为 0.5，仍分别位于原来的四个象限。</li><li>比较输入与判决索引：在本例没有噪声、没有旋转、正实数缩放的条件下，判决仍应一致。解释为什么“点没有落在原预设位置上”不一定导致判错——最近的那个点仍是同一个编号。</li><li>恢复增益实部 1，重新运行，再把工程另存为个人练习。</li></ol><p>不要将这条结论推广为“信号再弱也不出错”。本例缩小坐标时没有额外加入接收噪声；真实信号减弱而噪声不随之等比例减小时，判决条件会改变。也不要只改一个模块为 BPSK 就沿用其余 QPSK 设置；更换码元体系需要整条链一致，本课不把它当作单参数练习。</p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>检查方法</th></tr></thead><tbody><tr><td>只出现两三个点</td><td>先检查随机区间是否仍为 <code>[0,4)</code>，再检查是否只保留了很少样本</td></tr><tr><td>星座位置对，判回编号错</td><td>核对源、映射器、判决器的模式、点表顺序、D 和归一化；位置集合相同不代表编号相同</td></tr><tr><td>想看码元的模拟频谱但没有候选</td><td>编号是离散选择，不能直接当模拟幅度；可观察映射后的复数频谱，但要说明未成形的离散模型</td></tr><tr><td>星座选项不可选</td><td>恰好捕获一路复数输出；索引输出属于码元类型，不能用星座显示</td></tr><tr><td>加入信道后逐项比较出现差异</td><td>本课没有信道节点；综合示例中的原生信道存在前视，必须先核对时间／索引对应关系，不能直接算误码率</td></tr></tbody></table><p>你现在已经区分了“数据内容—码元编号—复数坐标—接收判决”。回到<a href="./../">学习路径</a>，可选择保留的 QPSK 综合工程继续研究信道；其中的额外行为应按该例说明核对，本课的理想直连结论不自动适用。</p><p>模块参考：<a href="./../../modules/random_symbols/">随机码元发生器</a> · <a href="./../../modules/symbol_mapper/">符号映射器</a> · <a href="./../../modules/complex_gain/">复数增益器</a> · <a href="./../../modules/symbol_slicer/">符号判决器</a></p>',29)])])}const m=a(o,[["render",n]]);export{g as __pageData,m as default};
